9	/**
10	 * Runs in {@code POST /api/owners} after the uniqueness checks, reading the already-validated
11	 * body as a variable. Rejects the request when its city (compared case-insensitively) already
12	 * holds {@link #CITY_CAPACITY} or more owners, throwing {@link CityAtCapacityException} for a
13	 * 409 before any entity is built or persisted. Reads the count in the same transaction as the
14	 * writes.
15	 */
16	public class EnsureCityHasCapacity {
17	
18	    /** Maximum number of owners a single city may hold. */
19	    static final int CITY_CAPACITY = 50;
20	
21	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
22	            throws CityAtCapacityException {
23	
24	        long cityCount = ownerRepository.findAll().stream()
25	                .filter(existing -> request.getCity().equalsIgnoreCase(existing.getCity()))
26	                .count();
27	        if (cityCount >= CITY_CAPACITY) {
28	            throw new CityAtCapacityException(request.getCity());
29	        }
30	    }
