10	/**
11	 * Resolves the effective registration date for {@code POST /api/owners}: the date supplied in
12	 * the body, or the server's current date when none was supplied, rolled forward to the next
13	 * business day when it falls on a weekend. Publishes it so the daily-capacity check counts
14	 * against the adjusted business day and {@link ApplyOwnerRegistrationDate} stamps the same
15	 * value onto the built owner. Runs after validation and before the daily-capacity check.
16	 */
17	public class ResolveOwnerRegistrationDate {
18	
19	    public void service(@Val OwnerFieldsDto request, Out<LocalDate> registrationDate) {
20	        LocalDate supplied = request.getRegistrationDate();
21	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
22	        registrationDate.set(BusinessDay.rollForward(effective));
23	    }
24	}
