9	/**
10	 * Runs in {@code POST /api/owners} before any entity is built or persisted. Rejects the
11	 * request when the resolved business day (the adjusted registrationDate from
12	 * {@link ResolveOwnerRegistrationDate}) has already reached {@link #DAILY_LIMIT} owner
13	 * registrations, throwing {@link DailyOwnerLimitException} for a 429. Reads the count in the
14	 * same transaction as the writes so the per-day cap is enforced consistently.
15	 */
16	public class EnsureDailyOwnerCapacity {
17	
18	    /** Maximum number of owners that may be registered in a single business day. */
19	    static final int DAILY_LIMIT = 100;
20	
21	    public void service(@Val LocalDate registrationDate, OwnerRepository ownerRepository)
22	            throws DailyOwnerLimitException {
23	
24	        long dayCount = ownerRepository.findAll().stream()
25	                .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
26	                .count();
27	        if (dayCount >= DAILY_LIMIT) {
28	            throw new DailyOwnerLimitException(registrationDate);
29	        }
30	    }
31	}
