1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Optional;
4	
5	/**
6	 * Telephone normalization shared by the owner pipelines: converts a supplied telephone to
7	 * canonical E.164 form (a leading {@code +}, country code, then national digits), so an
8	 * owner's telephone is stored, returned and compared in one representation.
9	 */
10	public final class OwnerTelephone {
11	
12	    /** Country code assumed when the input carries no explicit {@code +} prefix. */
13	    private static final String DEFAULT_COUNTRY_CODE = "61";
14	
15	    /** E.164 allows between 8 and 15 digits after the {@code +}. */
16	    private static final int MIN_DIGITS = 8;
17	    private static final int MAX_DIGITS = 15;
18	
19	    private OwnerTelephone() {
20	    }
21	
22	    /**
23	     * The E.164 form of {@code telephone}, or {@link Optional#empty()} when it cannot form a
24	     * valid E.164 number. Spaces, dashes and brackets are stripped. A leading {@code +} keeps
25	     * the given country code; otherwise country code {@code +61} is assumed and a single
26	     * leading {@code 0} is dropped from the national digits. The result must carry 8 to 15
27	     * digits after the {@code +}.
28	     */
29	    public static Optional<String> toE164(String telephone) {
30	        if (telephone == null) {
31	            return Optional.empty();
32	        }
33	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
34	        String digits;
35	        if (cleaned.startsWith("+")) {
36	            digits = cleaned.substring(1);
37	        }
38	        else {
39	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
40	            digits = DEFAULT_COUNTRY_CODE + national;
41	        }
42	        if (!digits.matches("[0-9]{" + MIN_DIGITS + "," + MAX_DIGITS + "}")) {
43	            return Optional.empty();
44	        }
45	        return Optional.of("+" + digits);
46	    }
47	}
