4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	/**
9	 * Identity of an owner's household. Two owners live in the same household when they share
10	 * the same last name and address. The address is compared in its {@link OwnerAddress
11	 * normalized} form and the last name case-insensitively with collapsed whitespace.
12	 *
13	 * <p>The {@link #id(String, String) household id} is derived deterministically from that
14	 * canonical key, so every member of a household computes the same stable identifier without
15	 * needing to coordinate.
16	 */
17	final class Household {
18	
19	    private Household() {
20	    }
21	
22	    /**
23	     * Canonical household key: the last name trimmed, internal whitespace collapsed and
24	     * lower-cased, and the address in its {@link OwnerAddress normalized} form, joined so
25	     * distinct pairs never collide.
26	     */
27	    static String key(String lastName, String address) {
28	        return canonical(lastName) + "\n" + OwnerAddress.normalize(address);
29	    }
30	
31	    /** Whether the two (last name, address) pairs belong to the same household. */
32	    static boolean same(String lastNameA, String addressA, String lastNameB, String addressB) {
33	        return key(lastNameA, addressA).equals(key(lastNameB, addressB));
34	    }
35	
36	    /**
37	     * Stable identifier shared by every owner in the household — the SHA-256 hex digest of the
38	     * canonical {@link #key(String, String) key}, so any member derives the same value.
39	     */
40	    static String id(String lastName, String address) {
41	        return sha256Hex(key(lastName, address));
42	    }
43	
44	    /** Case-insensitive form with leading/trailing and repeated internal whitespace collapsed. */
45	    private static String canonical(String value) {
46	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
47	    }
48	
49	    private static String sha256Hex(String value) {
50	        try {
51	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
52	            StringBuilder sb = new StringBuilder(digest.length * 2);
53	            for (byte b : digest) {
54	                sb.append(String.format("%02x", b));
55	            }
56	            return sb.toString();
57	        }
58	        catch (NoSuchAlgorithmException e) {
59	            throw new IllegalStateException("SHA-256 not available", e);
60	        }
61	    }
62	}
