3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	
6	/**
7	 * Business-day helpers for the owner registration date.
8	 */
9	public final class BusinessDay {
10	
11	    private BusinessDay() {
12	    }
13	
14	    /**
15	     * Rolls a weekend date forward to the following Monday: a Saturday or Sunday becomes the
16	     * next Monday, while a weekday is returned unchanged.
17	     */
18	    public static LocalDate rollForward(LocalDate date) {
19	        DayOfWeek day = date.getDayOfWeek();
20	        if (day == DayOfWeek.SATURDAY) {
21	            return date.plusDays(2);
22	        }
23	        if (day == DayOfWeek.SUNDAY) {
24	            return date.plusDays(1);
25	        }
26	        return date;
27	    }
